diff_snippets:
modules/gpu_node_pool/main.tf: resource "google_container_node_pool" "gpu_pool" {
  initial_node_count = var.initial_node_count
  autoscaling {
    min_node_count = var.min_count
    max_node_count = var.max_count
  }
  node_config {
    guest_accelerator { type = var.gpu_type; count = var.gpu_count }
    metadata = var.kubelet_metadata
    taints = var.gpu_taints
    labels = merge(var.node_labels, {
      "redwood.nodepool" = var.name
    })
  }
}
modules/iam_instance_profile/main.tf: data "aws_iam_policy_document" "ssm_cloudwatch" {
  statement {
    actions = ["ssm:DescribeInstanceInformation", "ssm:GetParameter"]
    resources = ["*"]
  }
}
resource "aws_iam_role" "gpu_node_role" {
  assume_role_policy = data.aws_iam_policy_document.ssm_cloudwatch.json
}
scripts/migrate-state.sh: #!/usr/bin/env bash
